from pathlib import Path
import base64, gzip

README_OLD = '- 2026-08-05：阶段 2 Atomic Task 2.4（App Shell）已实施并进入正式复验：新增 `createUI(root)` 与按职责拆分的菜单、工具栏、侧栏、工作区、状态栏和 overlay 壳模块，严格返回 `menu/toolbar/sidebar/editor/preview/status/overlay` refs；兼容 HTML 已拆为 8 个显式业务内容模板并仅挂入新壳，不再拥有第二套生产壳结构。依赖无关的专项契约、历史基线、模块清单、源码语法和差异检查已通过；完整 Node、架构、浏览器、构建与桌面链路等待 GitHub CI 验证，Atomic Task 2.5 尚未开始。'
README_NEW = '- 2026-08-05：阶段 2 Atomic Task 2.4（App Shell）完成：新增 `createUI(root)` 与按职责拆分的菜单、工具栏、侧栏、工作区、状态栏和 overlay 壳模块，严格返回 `menu/toolbar/sidebar/editor/preview/status/overlay` refs；兼容 HTML 拆为 `menu/toolbar/sidebar/editor/preview/status/overlay/ports` 八个显式业务内容模板并只挂入唯一新壳。实现代码提交 `660c0e22312f41885ca6c86078b2f0189541d5e9`，清理验证头 `b5bc87719e71b9ac27c0bc2512ba9121a4e24d07` 的 Stage 2 run `31009862503`、Stage 1 run `31009862345`、Stage 0 run `31009863167` 全部通过；生产模块记录为 79，未修改 CSS、Rust、依赖、锁文件、冻结模型、持久化或用户行为，Atomic Task 2.5 尚未开始。'
DOC_GZIP_B64 = ''

readme = Path("README.md")
text = readme.read_text(encoding="utf-8")
if text.count(README_OLD) != 1:
    raise SystemExit(f"expected one pending 2.4 README line, found {text.count(README_OLD)}")
